// Web Push for the dictation's service worker, pulled in by importScripts
// (vite.config.ts, workbox.importScripts). The service worker itself is still
// generated by vite-plugin-pwa: its caching is untouched, this file only adds
// two listeners (brief §9, research H).
//
// A notification carries { title, body, url, tag } and nothing else — never
// a summary, never a transcript.

self.addEventListener("push", (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = { title: event.data ? event.data.text() : "" };
  }
  const title = data.title || "Mosaic Dictée";
  event.waitUntil(
    self.registration.showNotification(title, {
      body: data.body || "",
      tag: data.tag || undefined,
      icon: "/icon-192.png",
      badge: "/icon-192.png",
      lang: "fr",
      data: { url: data.url || "/" },
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = new URL(event.notification.data?.url || "/", self.location.origin);
  event.waitUntil(
    (async () => {
      // A Notion page opens where Notion lives; the app is not the place.
      if (target.origin !== self.location.origin) {
        await self.clients.openWindow(target.href);
        return;
      }
      // The app already open: brought forward and told where to go, rather
      // than opened a second time.
      const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      const open = windows.find((client) => new URL(client.url).origin === self.location.origin);
      if (open) {
        await open.focus();
        open.postMessage({ open: target.pathname + target.search });
        return;
      }
      await self.clients.openWindow(target.href);
    })(),
  );
});
